P.reactionFor=function(t,element,o={}){element=el(element);
 // In this existing single-reaction model, a confirmed blunt hit spends Frozen before elemental amplification.
 if(st(t,'STATUS_FREEZE')&&(element==='바위'||o.blunt||/둔중|\bBLUNT\b/.test((o.tags||[]).join(' ')))){const shatter=this.tables['37_ELEMENTAL_REACTION_DB'].get('RX_SHATTER');if(shatter)return [...shatter];}
 if(o.noAura)return null;
 const auras=this.auraList(t).map(x=>x.element),candidates=[];for(const r of this.combatRows('37_ELEMENTAL_REACTION_DB')){if(!String(r[0]).startsWith('RX_')||/LUNAR|STELLAR/.test(r[0])||r[0]==='RX_SHATTER')continue;const aura=auras.find(x=>String(r[2]).split('/').includes(x)&&x!==element);let match=aura&&String(r[3]).split('/').includes(element);if(['RX_AGGRAVATE','RX_SPREAD'].includes(r[0]))match=!!st(t,'QUICKEN')&&String(r[3]).split('/').includes(element);if(['RX_HYPERBLOOM','RX_BURGEON'].includes(r[0]))match=String(r[3]).split('/').includes(element)&&this.s.runtime.fields.some(f=>f.kind==='DENDRO_CORE'&&!f.done&&this.combatDistance(t,f)===0);if(match)candidates.push(Object.assign([...r],{previousAura:aura}));}return candidates.sort((a,b)=>Number(b[12])-Number(a[12]))[0]||null;};

